  const { filename, bytes: b } = intake;
  const ext = filename ? filename.split('.').pop().toLowerCase() : '';
  const isNiftiExt = ext === 'nii' || ext === 'hdr' || ext === 'img';

  if (!b || b.length < 350) return isNiftiExt ? 0.5 : 0;

  // NIfTI-1: sizeof_hdr = 348
